  const REACT_QUICK = ['👍', '😂', '🔥', '❤️', '😮', '😢', '👏'];
  // (an emoji, or a server emote's exact ":name:")
  const reactEmote = e => /^:[A-Za-z0-9_]{2,32}:$/.test(e) ? EMOTES.get(e.slice(1, -1)) || null : null;
  const REACT_OK = e => typeof e === 'string' && ((e.length <= 24 && !/[\s\x00-\x1f\x7f;\\]/.test(e) && !/[A-Za-z0-9]/.test(e)) || !!reactEmote(e));
