    const RANK = { '~': 0, '&': 1, '@': 2, '%': 3 };
    const rank = r => r.pre in RANK ? RANK[r.pre] : r.op ? RANK['@'] : r.bot ? 4 : 5;
    rows.sort((a, b) => ((a.aw != null) - (b.aw != null)) || (rank(a) - rank(b)) || a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }));
