    for (const c of nicoCmds(t)) {
      const k = Object.keys(GROUP).find(g => GROUP[g].includes(c));
      if (k) { if (!st[k]) st[k] = c; } else if (isColor(c)) { if (!st.color) st.color = c; } else st.rest.push(c);
    }
