    cb.addEventListener('change', () => { behind = cb.checked; store.set('mbaa-chat-behind', behind); const M = glovReady(); if (M) { M._viewer_ov_behind(behind ? 1 : 0); if (M._viewer_represent) M._viewer_represent(); } cb.blur(); });
